/* ============================================================
   scene/engine.js — 3D Reaktif Sahne Motoru v4.1
   ------------------------------------------------------------
   Bu modül NurseKit'in 3D motorunun çekirdeğidir:
     • State: three, SceneAssets, EmbeddedGLBAssets, ROOM_CAMERA_PRESETS
     • Yaşam döngüsü: initThree, disposeThree, buildSceneForRoom
     • Kamera: getCameraPreset, focusCameraPreset, setFocusMode
     • Render loop: animateScene, updateCam, resizeThree
     • Geometri helper'ları: mat, box, cyl, sphere, prepMesh, groupAt
     • Yerleşim (placement) kontrolleri
     • Oda kabuğu (buildRoomShell)
     • Obje kaydı: addObj, addDecor, addAnimated

   Bağımlılıklar (main-app.js'ten):
     - var App                       (app state)
     - THREE                         (global, CDN)
     - taskByKeywords / taskByKeywordsForPhase, taskDone, taskStatusClass
     - statusMarker, applyMarkerVisibility, updateMarkerColors
     - buildPatient, buildBed, buildMonitor, ...build* fonksiyonları
     - $, el                         (DOM helper'ları)
     - getCompletedMarkerStore, gcklBoardSyncMarkerState

   Bu dosya core/main-app.js'TEN SONRA yüklenir; içerdiği
   function declaration'lar otomatik olarak global scope'a
   kaydolur, böylece main-app.js (ve diğer modüller)
   initThree/disposeThree/buildSceneForRoom vb. çağırabilir.
   ============================================================ */

        /* ===================== 3D REAKTİF SAHNE MOTORU v4.1 ===================== */
        var three = { 
            renderer: null, scene: null, camera: null, animId: null, clock: null,
            objects: [], animated: [], markers: [], roomShell: null, gltfModel: null, gltfMixer: null,
            spherical: { theta: 0.44, phi: 1.16, radius: 9.6 }, lookAtTarget: { x: 0, y: 1.34, z: -0.15 }, dragging: false, prev: { x: 0, y: 0 },
            lastSignature: '', lastCriticalMissing: -1, keyState: {}, keyBound: false, placement: { panelOpen: false, enabled: false, selected: null, saved: {}, locked: {} }
        };


        var EmbeddedGLBAssets = {
            preop: '',
            intraop: '',
            postop: ''
        };

        var SceneAssets = {
            defaultPaths: {
                preop: 'assets/models/preop_room.glb',
                intraop: 'assets/models/or_room.glb',
                postop: 'assets/models/pacu_room.glb'
            },
            embeddedURLs: { preop: null, intraop: null, postop: null },
            localURLs: { preop: null, intraop: null, postop: null },
            keepPrimitiveShell: true,
            controlsAttached: false,
            loadToken: 0
        };

        function ensureEmbeddedModelURLs() {
            Object.keys(EmbeddedGLBAssets).forEach((room) => {
                if (SceneAssets.embeddedURLs[room]) return;
                try {
                    const b64 = EmbeddedGLBAssets[room];
                    const binary = atob(b64);
                    const len = binary.length;
                    const bytes = new Uint8Array(len);
                    for (let i = 0; i < len; i++) bytes[i] = binary.charCodeAt(i);
                    const blob = new Blob([bytes], { type: 'model/gltf-binary' });
                    SceneAssets.embeddedURLs[room] = URL.createObjectURL(blob);
                } catch (err) {
                    console.warn('Embedded GLB URL oluşturulamadı:', room, err);
                }
            });
        }

        function attachSceneAssetControls() {
            if (SceneAssets.controlsAttached) return;
            SceneAssets.controlsAttached = true;
            const panel = $('#scene-asset-panel');
            const toggle = $('#scene-asset-toggle');
            const file = $('#scene-model-file');
            const defBtn = $('#scene-model-default');
            const clearBtn = $('#scene-model-clear');
            const shellBtn = $('#scene-model-shell');

            toggle && (toggle.onclick = () => {
                panel?.classList.toggle('collapsed');
                toggle.textContent = panel?.classList.contains('collapsed') ? 'Aç' : 'Kapat';
            });
            file && (file.onchange = () => {
                const f = file.files && file.files[0];
                if (!f) return;
                const room = App.currentRoom || 'preop';
                if (SceneAssets.localURLs[room]) URL.revokeObjectURL(SceneAssets.localURLs[room]);
                SceneAssets.localURLs[room] = URL.createObjectURL(f);
                updateAssetStatus(`Yükleniyor: ${f.name}`);
                buildSceneForRoom();
            });
            defBtn && (defBtn.onclick = () => {
                const room = App.currentRoom || 'preop';
                if (SceneAssets.localURLs[room]) {
                    URL.revokeObjectURL(SceneAssets.localURLs[room]);
                    SceneAssets.localURLs[room] = null;
                }
                updateAssetStatus('Entegre animasyonlu oda sahnesi geri yükleniyor.');
                buildSceneForRoom();
            });
            clearBtn && (clearBtn.onclick = () => {
                const room = App.currentRoom || 'preop';
                if (SceneAssets.localURLs[room]) URL.revokeObjectURL(SceneAssets.localURLs[room]);
                SceneAssets.localURLs[room] = null;
                if (three.gltfModel) { three.scene.remove(three.gltfModel); three.gltfModel = null; three.gltfMixer = null; }
                if (three.roomShell) three.roomShell.visible = true;
                updateAssetStatus('Haricî model kaldırıldı. temiz klinik sahne tekrar etkinleştirildi.');
                showSceneReaction('Haricî model kaldırıldı; ana premium sahne kullanılmaya devam ediyor.', 'info');
            });
            shellBtn && (shellBtn.onclick = () => {
                SceneAssets.keepPrimitiveShell = !SceneAssets.keepPrimitiveShell;
                shellBtn.textContent = 'Yerleşik kabuk: ' + (SceneAssets.keepPrimitiveShell ? 'Açık' : 'Kapalı');
                if (three.roomShell) three.roomShell.visible = SceneAssets.keepPrimitiveShell || !three.gltfModel;
                updateAssetStatus('Bu sürümde görünür ana yapı premium entegre sahnedir.');
            });
        }

        function updateAssetStatus(msg) {
            const elStatus = $('#scene-asset-status');
            if (elStatus) elStatus.textContent = msg;
        }

        function addShellDecor(mesh) {
            if (!three.scene) return mesh;
            if (!three.roomShell) {
                three.roomShell = new THREE.Group();
                three.roomShell.name = 'BuiltInWideRoomShell';
                three.scene.add(three.roomShell);
            }
            three.roomShell.add(mesh);
            return mesh;
        }

        function loadProfessionalModelForRoom(room, forceDefault = false) {
            if (!three.scene) return;
            if (three.gltfModel) { three.scene.remove(three.gltfModel); three.gltfModel = null; three.gltfMixer = null; }
            if (!THREE.GLTFLoader) {
                updateAssetStatus('GLTFLoader yüklenemedi; yerleşik 3D oda kullanılıyor. İnternet/CDN erişimini kontrol edin.');
                if (three.roomShell) three.roomShell.visible = true;
                return;
            }
            const url = SceneAssets.localURLs[room] || (forceDefault ? (SceneAssets.embeddedURLs[room] || SceneAssets.defaultPaths[room]) : null);
            if (!url) {
                updateAssetStatus('temiz klinik sahne hazır. İsterseniz yalnızca bu faz için farklı bir GLB/GLTF yükleyebilirsiniz.');
                if (three.roomShell) three.roomShell.visible = true;
                return;
            }
            const token = ++SceneAssets.loadToken;
            const loader = new THREE.GLTFLoader();
            loader.load(url, (gltf) => {
                if (token !== SceneAssets.loadToken) return;
                const model = gltf.scene || gltf.scenes?.[0];
                if (!model) {
                    updateAssetStatus('Model okundu ancak sahne içermiyor; yerleşik 3D oda korunuyor.');
                    return;
                }
                model.name = 'ProfessionalHospitalModel_' + room;
                model.position.set(0, 0, 0);
                model.rotation.set(0, 0, 0);
                const scale = room === 'intraop' ? 1.02 : 1.0;
                model.scale.setScalar(scale);
                model.traverse((child) => {
                    if (child.isMesh) {
                        child.castShadow = true;
                        child.receiveShadow = true;
                        const mats = Array.isArray(child.material) ? child.material : [child.material];
                        mats.forEach((mat) => {
                            if (!mat) return;
                            if (typeof mat.roughness === 'number') mat.roughness = Math.min(0.92, Math.max(0.28, mat.roughness));
                            if (typeof mat.metalness === 'number') mat.metalness = Math.min(0.38, Math.max(0.02, mat.metalness));
                            if ('envMapIntensity' in mat) mat.envMapIntensity = 1.15;
                            mat.needsUpdate = true;
                        });
                        child.userData.isExternalModel = true;
                    }
                });
                three.scene.add(model);
                three.gltfModel = model;
                if (gltf.animations && gltf.animations.length) {
                    three.gltfMixer = new THREE.AnimationMixer(model);
                    gltf.animations.slice(0, 4).forEach(clip => three.gltfMixer.clipAction(clip).play());
                }
                if (three.roomShell) three.roomShell.visible = SceneAssets.keepPrimitiveShell;
                updateAssetStatus('Haricî GLB sahne aktif. Klinik etkileşimler ve puanlama korunuyor.');
                showSceneReaction('Entegre Animasyonlu Hastane Odası yüklendi. Klinik görevler ve GCKL etkileşimleri korunuyor.', 'ok');
            }, undefined, () => {
                if (token !== SceneAssets.loadToken) return;
                if (three.roomShell) three.roomShell.visible = true;
                updateAssetStatus('Model yüklenemedi. Sistem güvenli şekilde yerleşik geniş tavanlı 3D odaya döndü.');
            });
        }

        function initThree() { 
            attachSceneAssetControls();
            loadPlacementState();
            attachPlacementControls();
            ensureEmbeddedModelURLs();
            buildSceneForRoom();
            const cv = $('#three-canvas');
            cv.onmousedown = (e) => { three.dragging = true; three.prev = { x: e.clientX, y: e.clientY }; };
            window.addEventListener('mouseup', () => three.dragging = false);
            if (!three.keyBound) {
                three.keyBound = true;
                window.addEventListener('keydown', (e) => {
                    const k = (e.key || '').toLowerCase();
                    if (['w','a','s','d','q','e','z','x','r','arrowup','arrowdown','arrowleft','arrowright','+','=','-','_','shift'].includes(k)) e.preventDefault();
                    three.keyState[k] = true;
                });
                window.addEventListener('keyup', (e) => {
                    const k = (e.key || '').toLowerCase();
                    delete three.keyState[k];
                });
            }
            cv.onmousemove = (e) => { 
                if (!three.dragging) return;
                const dx = (e.clientX - three.prev.x) * 0.005;
                const dy = (e.clientY - three.prev.y) * 0.005;
                three.spherical.theta -= dx;
                three.spherical.phi = Math.max(0.08, Math.min(1.82, three.spherical.phi + dy));
                three.prev = { x: e.clientX, y: e.clientY };
                updateCam(); 
            };
            cv.onwheel = (e) => { e.preventDefault(); three.spherical.radius = Math.max(1.6, Math.min(36.0, three.spherical.radius + e.deltaY * 0.01)); updateCam(); };
            cv.onclick = onCanvasClick;
            window.addEventListener('resize', resizeThree); 
        }

        function disposeThree() { 
            if (typeof SceneAssets !== 'undefined') SceneAssets.loadToken++;
            if (three.renderer) { cancelAnimationFrame(three.animId); three.renderer.dispose(); }
            three.objects = []; three.animated = []; three.markers = []; three.monitorSoundToggles = []; three.roomShell = null; three.gltfModel = null; three.gltfMixer = null; three.lastSignature = '';
        }

        


        function getPhaseCameraFocusHint(room = App.currentRoom) {
            if (room === 'preop') return 'Odak: hasta başı + dosya/onam-NPO paneli';
            if (room === 'intraop') return 'Odak: steril alan + ekip dizilimi + time-out';
            if (room === 'postop') return 'Odak: hasta başı + monitör + dren/ağrı hattı';
            return 'Odak: klinik karar noktası';
        }

        var ROOM_CAMERA_PRESETS = {
            preop: {
                phase: { theta: -0.86, phi: 1.08, radius: 10.4, lookAt: { x: 1.2, y: 1.28, z: -0.42 } },
                wide:  { theta: -0.72, phi: 1.14, radius: 12.8, lookAt: { x: 0.3, y: 1.22, z: -0.18 } },
                close: { theta: -1.02, phi: 1.05, radius: 7.9,  lookAt: { x: 2.0, y: 1.34, z: -0.55 } }
            },
            intraop: {
                phase: { theta: 0.34, phi: 0.96, radius: 12.7, lookAt: { x: 0.15, y: 1.42, z: 0.05 } },
                wide:  { theta: 0.48, phi: 1.02, radius: 14.6, lookAt: { x: 0.10, y: 1.32, z: 0.02 } },
                close: { theta: 0.12, phi: 0.92, radius: 9.4,  lookAt: { x: 0.35, y: 1.45, z: 0.18 } }
            },
            postop: {
                phase: { theta: -0.70, phi: 1.08, radius: 10.8, lookAt: { x: 0.70, y: 1.30, z: -0.25 } },
                wide:  { theta: -0.56, phi: 1.13, radius: 12.8, lookAt: { x: 0.10, y: 1.24, z: -0.05 } },
                close: { theta: -0.92, phi: 1.04, radius: 8.1,  lookAt: { x: 1.35, y: 1.36, z: -0.50 } }
            }
        };


        function getCameraPreset(room = App.currentRoom, focus = App.cameraFocus || 'phase') {
            const roomSet = ROOM_CAMERA_PRESETS[room] || ROOM_CAMERA_PRESETS.preop;
            return roomSet[focus] || roomSet.phase || ROOM_CAMERA_PRESETS.preop.phase;
        }
        function focusCameraPreset(focus = 'phase') {
            App.cameraFocus = focus;
            if (!three.camera || !three.spherical) return;
            const preset = getCameraPreset(App.currentRoom, focus);
            three.spherical.theta = preset.theta;
            three.spherical.phi = preset.phi;
            three.spherical.radius = preset.radius;
            three.lookAtTarget = { ...preset.lookAt };
            updateCam();
            showSceneReaction(focus === 'wide' ? 'Kamera geniş oda görünümüne geçti.' : (focus === 'close' ? 'Kamera kritik bakım noktasına yakınlaştı.' : 'Kamera faza uygun klinik odak noktasına döndü.'), 'info');
        }
        function bindCameraFocusButtons() {
            document.querySelectorAll('[data-cam-focus]').forEach(btn => {
                btn.onclick = (ev) => {
                    ev.preventDefault(); ev.stopPropagation();
                    focusCameraPreset(btn.getAttribute('data-cam-focus') || 'phase');
                };
            });
            // Focus mode segmented buttons
            document.querySelectorAll('[data-focus-mode]').forEach(btn => {
                btn.onclick = (ev) => {
                    ev.preventDefault(); ev.stopPropagation();
                    const mode = btn.getAttribute('data-focus-mode') || 'task';
                    setFocusMode(mode);
                };
            });
            // Reflect current state on bind
            updateFocusModeButtonsActive();
        }
        function updateFocusModeButtonsActive() {
            const mode = App.focusMode || 'task';
            document.querySelectorAll('[data-focus-mode]').forEach(btn => {
                if (btn.getAttribute('data-focus-mode') === mode) btn.classList.add('active');
                else btn.classList.remove('active');
            });
        }
        function setFocusMode(mode) {
            if (!['task','safety','free'].includes(mode)) mode = 'task';
            App.focusMode = mode;
            updateFocusModeButtonsActive();
            applyMarkerVisibility();
            const labels = { task:'Görev modu — aktif ve kritik işaretler.', safety:'Güvenlik modu — yalnızca kritik güvenlik işaretleri.', free:'Serbest mod — tüm işaretler görünür, pasifler soluk.' };
            showSceneReaction(labels[mode], mode === 'safety' ? 'warn' : 'info');
        }

        function buildSceneForRoom() { 
            disposeThree();
            const cv = $('#three-canvas'); if (!cv || !App.currentPatient) return;
            const cont = $('#scene-shell');
            const W = cont.offsetWidth;
            const H = Math.max(280, cont.offsetHeight - 50);
            three.renderer = new THREE.WebGLRenderer({ canvas: cv, antialias: true, alpha: true });
            three.renderer.setSize(W, H);
            three.renderer.setPixelRatio(Math.min(2, window.devicePixelRatio || 1));
            three.renderer.shadowMap.enabled = true;
            three.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
            if ('outputEncoding' in three.renderer) three.renderer.outputEncoding = THREE.sRGBEncoding;
            if ('toneMapping' in three.renderer) three.renderer.toneMapping = THREE.ACESFilmicToneMapping;
            if ('toneMappingExposure' in three.renderer) three.renderer.toneMappingExposure = App.currentRoom === 'intraop' ? 1.28 : 1.18;
            if ('physicallyCorrectLights' in three.renderer) three.renderer.physicallyCorrectLights = true;
            three.scene = new THREE.Scene();
            three.scene.fog = new THREE.Fog(App.currentRoom === 'intraop' ? 0xdbe6ec : 0xd7e0e8, 20, 52);
            three.camera = new THREE.PerspectiveCamera(50, W / H, 0.1, 100);
            three.clock = new THREE.Clock();
            const camPreset = getCameraPreset(App.currentRoom, App.cameraFocus || 'phase');
            three.spherical = { theta: camPreset.theta, phi: camPreset.phi, radius: camPreset.radius };
            three.lookAtTarget = { ...camPreset.lookAt };
            updateCam();

            const roomTone = App.currentRoom === 'intraop' ? 0x0b1724 : (App.currentRoom === 'postop' ? 0x0d1d2a : 0x0d1b2e);
            const hemi = new THREE.HemisphereLight(0xf4fbff, 0x7f9aa8, App.currentRoom === 'intraop' ? 1.05 : 1.10);
            three.scene.add(hemi);
            const ambient = new THREE.AmbientLight(0xffffff, App.currentRoom === 'intraop' ? 0.42 : 0.48);
            three.scene.add(ambient);
            const key = new THREE.DirectionalLight(0xffffff, App.currentRoom === 'intraop' ? 1.42 : 1.14);
            key.position.set(4.8, 8.4, 5.6); key.castShadow = true;
            key.shadow.mapSize.width = 2048; key.shadow.mapSize.height = 2048;
            key.shadow.camera.near = 0.5; key.shadow.camera.far = 28;
            three.scene.add(key);
            const fill = new THREE.PointLight(0x86b9df, 0.48, 18);
            fill.position.set(-4.2, 2.9, 2.6); three.scene.add(fill);
            const tealLight = new THREE.PointLight(0x5cc4d6, 0.56, 14);
            tealLight.position.set(-3.2, 3.2, 1.8); three.scene.add(tealLight);
            const rim = new THREE.PointLight(0xe8eef5, 0.36, 22);
            rim.position.set(0.0, 3.6, -5.8); three.scene.add(rim);
            const warmSide = new THREE.PointLight(0xe0a558, App.currentRoom === 'preop' ? 0.28 : 0.12, 12);
            warmSide.position.set(3.8, 2.3, -3.2); three.scene.add(warmSide);
            const clinicalFocus = new THREE.SpotLight(0xffffff, App.currentRoom === 'intraop' ? 0.95 : 0.62, 18, Math.PI / 5.6, 0.42, 1.15);
            clinicalFocus.position.set(camPreset.lookAt.x + 1.6, 5.4, camPreset.lookAt.z + 2.2);
            clinicalFocus.target.position.set(camPreset.lookAt.x, camPreset.lookAt.y, camPreset.lookAt.z);
            three.scene.add(clinicalFocus.target);
            three.scene.add(clinicalFocus);

            buildRoomShell(roomTone);
            if (App.currentRoom === 'preop') buildPreop();
            else if (App.currentRoom === 'intraop') buildIntraop();
            else buildPostop();
            try { gcklBoardSyncMarkerState(); } catch(e) {}

            // Sahne kurulumu tamamlandıktan sonra marker görünürlüğünü uygula
            try { applyMarkerVisibility(); } catch (e) {}

            const sceneRoomLabel = $('#scene-room-label');
            if (sceneRoomLabel) {
                sceneRoomLabel.innerHTML = '';
                sceneRoomLabel.style.display = 'none';
            }
            loadProfessionalModelForRoom(App.currentRoom, false);
            three.animId && cancelAnimationFrame(three.animId);
            const tick = () => { 
                three.animId = requestAnimationFrame(tick); 
                animateScene();
                three.renderer.render(three.scene, three.camera); 
            };
            tick();
            resizeThree();
            updateProgressBar();
            bindCameraFocusButtons();
            showSceneReaction('Öğretici 3D sahne hazır: nesnelere tıklayarak klinik gerekçe, risk ve kontrol maddelerini inceleyebilirsiniz.', 'info');
        }

        function resizeThree() { 
            if (!three.renderer) return;
            const cont = $('#scene-shell');
            const W = cont.offsetWidth;
            const H = Math.max(280, cont.offsetHeight - 50);
            three.renderer.setSize(W, H);
            three.camera.aspect = W / H;
            three.camera.updateProjectionMatrix(); 
        }

        function updateCam() { 
            const s = three.spherical;
            const x = s.radius * Math.sin(s.phi) * Math.sin(s.theta);
            const y = s.radius * Math.cos(s.phi);
            const z = s.radius * Math.sin(s.phi) * Math.cos(s.theta); 
            if (three.camera) { const t = three.lookAtTarget || { x: 0, y: 1.28, z: -0.35 }; three.camera.position.set(x, y, z); three.camera.lookAt(t.x, t.y, t.z); } 
        }

        function animateScene() {
            if (!three.clock) return;
            const t = performance.now() * 0.001;
            const dt = three.clock.getDelta();
            if (three.gltfMixer) three.gltfMixer.update(dt);
            const pan = 4.8 * dt;
            const lift = 1.8 * dt;
            const zoom = 8.5 * dt;
            const ks = three.keyState || {};
            const placementMoved = moveSelectedPlacement(dt);
            if (!placementMoved) {
                if (ks['w'] || ks['arrowup']) three.lookAtTarget.z -= pan;
                if (ks['s'] || ks['arrowdown']) three.lookAtTarget.z += pan;
                if (ks['a'] || ks['arrowleft']) three.lookAtTarget.x -= pan;
                if (ks['d'] || ks['arrowright']) three.lookAtTarget.x += pan;
                if (ks['q']) three.lookAtTarget.y = Math.min(4.2, three.lookAtTarget.y + lift);
                if (ks['e']) three.lookAtTarget.y = Math.max(0.2, three.lookAtTarget.y - lift);
                if (ks['+'] || ks['=']) three.spherical.radius = Math.max(1.6, three.spherical.radius - zoom);
                if (ks['-'] || ks['_']) three.spherical.radius = Math.min(36.0, three.spherical.radius + zoom);
                if (Object.keys(ks).length) updateCam();
            }
            three.animated.forEach(a => {
                if (!a || !a.obj) return;
                if (a.type === 'breath') {
                    a.obj.scale.y = 1 + Math.sin(t * 2.2 + (a.phase || 0)) * 0.025;
                    a.obj.scale.z = 1 + Math.sin(t * 2.2 + (a.phase || 0)) * 0.018;
                } else if (a.type === 'pulse') {
                    const k = 0.45 + Math.abs(Math.sin(t * (a.speed || 2.4))) * 0.55;
                    if (a.obj.material && a.obj.material.emissive) a.obj.material.emissiveIntensity = (a.base || 0.35) + k * (a.amp || 0.45);
                } else if (a.type === 'spin') {
                    // Sürekli Y ekseni rotasyonu — KPB pompa rotorları, fan vs.
                    const axis = a.axis || 'y';
                    const speed = a.speed || 1.0;   // rad/saniye
                    a.obj.rotation[axis] += dt * speed;
                } else if (a.type === 'alarm') {
                    // Kritik marker artık yalnızca etiketle gösterilir; hafif nabız yeterlidir.
                    const k = 1 + Math.abs(Math.sin(t * (a.speed || 2.4))) * 0.05;
                    if (a.obj.visible) a.obj.scale.set(k, k, k);
                } else if (a.type === 'float') {
                    a.obj.position.y = a.baseY + Math.sin(t * (a.speed || 1.5) + (a.phase || 0)) * (a.amp || 0.04);
                    a.obj.rotation.y += dt * 0.35;
                } else if (a.type === 'complete-pulse') {
                    // 2-second green flash, scaling up then fading out
                    const elapsed = t - (a.start || t);
                    const dur = a.duration || 2.0;
                    if (elapsed >= dur) {
                        // Vurgu biter ama etiket görünür kalır; yalnızca normal duruma döner.
                        if (a.marker) {
                            a.marker.pulseActive = false;
                            a.marker.group.visible = true;
                            if (a.marker.labelSprite?.material) {
                                a.marker.labelSprite.material.opacity = 1;
                                a.marker.labelSprite.material.transparent = true;
                            }
                        }
                        a.obj.scale.set(1, 1, 1);
                        a.type = 'float';
                        a.baseY = a.marker?.baseY ?? a.baseY ?? a.obj.position.y;
                        a.speed = 1.0;
                        a.amp = 0.02;
                    } else {
                        const k = elapsed / dur; // 0 -> 1
                        // Scale: pop at start (1.0 -> 1.6 in first 0.3s), then settle to 1.0, fade in last 0.6s
                        let scale;
                        if (k < 0.15) {
                            scale = 1.0 + (k / 0.15) * 0.6;
                        } else if (k < 0.40) {
                            scale = 1.6 - ((k - 0.15) / 0.25) * 0.55;
                        } else {
                            scale = 1.05;
                        }
                        a.obj.scale.set(scale, scale, scale);
                        // Float vertically gently
                        a.obj.position.y = (a.baseY ?? a.obj.position.y) + Math.sin(t * 3.0) * 0.02;
                        // Opacity fade in last 40%
                        const opacity = k < 0.6 ? 1.0 : Math.max(0, 1.0 - (k - 0.6) / 0.4);
                        if (a.halo && a.halo.material) a.halo.material.opacity = 0.9 * opacity;
                        if (a.core && a.core.material) {
                            a.core.material.opacity = opacity;
                            a.core.material.transparent = true;
                        }
                        if (a.marker?.labelSprite?.material) {
                            a.marker.labelSprite.material.opacity = opacity;
                            a.marker.labelSprite.material.transparent = true;
                        }
                        // Emissive flash
                        const emK = 0.6 + Math.abs(Math.sin(elapsed * 6.0)) * 0.6;
                        if (a.halo && a.halo.material && a.halo.material.emissive) a.halo.material.emissiveIntensity = emK;
                        if (a.core && a.core.material && a.core.material.emissive) a.core.material.emissiveIntensity = emK + 0.2;
                    }
                }
            });
        }

        function mat(c, opts = {}) {
            const m = new THREE.MeshStandardMaterial({
                color: c,
                roughness: opts.roughness ?? 0.55,
                metalness: opts.metalness ?? 0.05,
                transparent: opts.transparent || false,
                opacity: opts.opacity ?? 1,
                emissive: opts.emissive || 0x000000,
                emissiveIntensity: opts.emissiveIntensity || 0
            });
            return m;
        }
        function box(w, h, d, c, x, y, z, opts = {}) { const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(c, opts)); m.position.set(x, y, z); prepMesh(m); return m; }
        function cyl(rt, rb, h, c, x, y, z, opts = {}) { const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, opts.seg || 20), mat(c, opts)); m.position.set(x, y, z); prepMesh(m); return m; }
        function sphere(r, c, x, y, z, opts = {}) { const m = new THREE.Mesh(new THREE.SphereGeometry(r, opts.w || 24, opts.h || 16), mat(c, opts)); m.position.set(x, y, z); prepMesh(m); return m; }
        function prepMesh(m) { m.castShadow = true; m.receiveShadow = true; return m; }
        function groupAt(x, y, z) { const g = new THREE.Group(); g.position.set(x, y, z); return g; }
        
        function placementSlug(s) {
            return String(s || '').toLocaleLowerCase('tr-TR')
                .replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ş/g,'s').replace(/ö/g,'o').replace(/ç/g,'c')
                .replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'').slice(0,80);
        }
        function placementKeyFor(obj) {
            const room = App.currentRoom || 'preop';
            const key = obj?.opts?.clinicalKey || obj?.label || 'object';
            return `${room}__${placementSlug(key)}__${placementSlug(obj?.label || '')}`;
        }
        function placementStorageKey() { return 'nursekit_custom_layout_v1'; }
        function loadPlacementState() {
            try {
                const raw = localStorage.getItem(placementStorageKey());
                const data = raw ? JSON.parse(raw) : {};
                three.placement.saved = data.saved || {};
                three.placement.locked = data.locked || {};
            } catch(e) {
                three.placement.saved = {};
                three.placement.locked = {};
            }
        }
        function savePlacementState() {
            try {
                localStorage.setItem(placementStorageKey(), JSON.stringify({ saved: three.placement.saved || {}, locked: three.placement.locked || {} }));
            } catch(e) { console.warn('Yerleşim kaydedilemedi', e); }
        }
        function applySavedPlacement(obj) {
            const k = placementKeyFor(obj);
            const p = three.placement?.saved?.[k];
            if (p && Number.isFinite(p.x) && Number.isFinite(p.z)) {
                obj.mesh.position.x = p.x;
                obj.mesh.position.z = p.z;
                if (Number.isFinite(p.ry)) obj.mesh.rotation.y = p.ry;
            }
            obj.opts = obj.opts || {};
            obj.opts.placementKey = k;
            obj.opts.locked = !!three.placement?.locked?.[k];
        }
        function persistObjectPlacement(obj) {
            if (!obj) return;
            const k = placementKeyFor(obj);
            three.placement.saved[k] = { x: +obj.mesh.position.x.toFixed(3), z: +obj.mesh.position.z.toFixed(3), ry: +obj.mesh.rotation.y.toFixed(4) };
            savePlacementState();
            updatePlacementPanel();
        }
        function setObjectLocked(obj, locked) {
            if (!obj) return;
            const k = placementKeyFor(obj);
            if (locked) three.placement.locked[k] = true;
            else delete three.placement.locked[k];
            obj.opts.locked = !!locked;
            savePlacementState();
            updatePlacementPanel();
        }
        function resetPlacementForRoom() {
            const room = App.currentRoom || 'preop';
            Object.keys(three.placement.saved || {}).forEach(k => { if (k.startsWith(room + '__')) delete three.placement.saved[k]; });
            Object.keys(three.placement.locked || {}).forEach(k => { if (k.startsWith(room + '__')) delete three.placement.locked[k]; });
            three.placement.selected = null;
            savePlacementState();
            buildSceneForRoom();
            updatePlacementPanel('Bu fazdaki özel yerleşim sıfırlandı.');
        }
        
        function rotateSelectedPlacement(deltaRad) {
            const obj = three.placement.selected;
            if (!obj) { updatePlacementPanel('Önce bir obje seç.'); return; }
            const k = placementKeyFor(obj);
            if (three.placement.locked[k]) { updatePlacementPanel('Bu obje kilitli. Döndürmek için önce kilidi aç.'); return; }
            obj.mesh.rotation.y += deltaRad;
            // keep value readable while still allowing full 360-degree cycling
            obj.mesh.rotation.y = ((obj.mesh.rotation.y % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
            persistObjectPlacement(obj);
            updatePlacementPanel(`${obj.label} döndürüldü.`);
        }
        function resetSelectedRotation() {
            const obj = three.placement.selected;
            if (!obj) { updatePlacementPanel('Önce bir obje seç.'); return; }
            const k = placementKeyFor(obj);
            if (three.placement.locked[k]) { updatePlacementPanel('Bu obje kilitli. Yönü sıfırlamak için önce kilidi aç.'); return; }
            obj.mesh.rotation.y = 0;
            persistObjectPlacement(obj);
            updatePlacementPanel(`${obj.label} yönü sıfırlandı.`);
        }

        function attachPlacementControls() {
            const panel = $('#placement-panel');
            const toggle = $('#placement-toggle');
            const enable = $('#placement-enable');
            const lock = $('#placement-lock');
            const unlock = $('#placement-unlock');
            const reset = $('#placement-reset');
            const rotLeft = $('#placement-rot-left');
            const rotRight = $('#placement-rot-right');
            const rotReset = $('#placement-rot-reset');
            const rotFree = $('#placement-rot-free');
            if (!panel || panel.dataset.bound === '1') return;
            panel.dataset.bound = '1';
            toggle && (toggle.onclick = () => {
                three.placement.panelOpen = !three.placement.panelOpen;
                panel.classList.toggle('collapsed', !three.placement.panelOpen);
                toggle.textContent = three.placement.panelOpen ? 'Kapat' : 'Aç';
            });
            enable && (enable.onclick = () => {
                three.placement.enabled = !three.placement.enabled;
                updatePlacementPanel(three.placement.enabled ? 'Yerleşim modu açık. Objeyi tıkla ve taşı.' : 'Yerleşim modu kapalı.');
            });
            lock && (lock.onclick = () => {
                if (!three.placement.selected) return updatePlacementPanel('Önce bir obje seç.');
                setObjectLocked(three.placement.selected, true);
            });
            unlock && (unlock.onclick = () => {
                if (!three.placement.selected) return updatePlacementPanel('Önce bir obje seç.');
                setObjectLocked(three.placement.selected, false);
            });
            reset && (reset.onclick = () => resetPlacementForRoom());
            rotLeft && (rotLeft.onclick = () => rotateSelectedPlacement(-Math.PI / 12));
            rotRight && (rotRight.onclick = () => rotateSelectedPlacement(Math.PI / 12));
            rotReset && (rotReset.onclick = () => resetSelectedRotation());
            rotFree && (rotFree.onclick = () => updatePlacementPanel('Sabit öğretici yerleşim kullanılıyor; öğrenci nesne konumu değiştirmez.'));
            updatePlacementPanel();
        }
        function updatePlacementPanel(msg) {
            const enable = $('#placement-enable');
            const selectedEl = $('#placement-selected');
            const status = $('#placement-status');
            if (enable) {
                enable.textContent = three.placement.enabled ? 'Mod: Açık' : 'Mod: Kapalı';
                enable.classList.toggle('active', !!three.placement.enabled);
            }
            const obj = three.placement.selected;
            if (selectedEl) {
                if (!obj) selectedEl.innerHTML = 'Seçili obje yok.';
                else {
                    const k = placementKeyFor(obj);
                    const locked = !!three.placement.locked[k];
                    const deg = (((obj.mesh.rotation.y * 180 / Math.PI) % 360) + 360) % 360;
                    selectedEl.innerHTML = `<b>${obj.label}</b><div class="placement-axis">X: ${obj.mesh.position.x.toFixed(2)} · Z: ${obj.mesh.position.z.toFixed(2)} · Yön: ${deg.toFixed(0)}° · ${locked ? 'Kilitli' : 'Açık'}</div>`;
                }
            }
            if (status) status.textContent = msg || (three.placement.enabled ? 'Sabit öğretici yerleşim açık. Nesneye tıkla ve öğrenme kartını incele.' : 'Sabit öğretici yerleşim açık. Nesneye tıkla ve öğrenme kartını incele.');
        }
        function selectPlacementObject(obj) {
            three.placement.selected = obj;
            if (!three.placement.panelOpen) {
                const panel = $('#placement-panel');
                const toggle = $('#placement-toggle');
                three.placement.panelOpen = true;
                panel?.classList.remove('collapsed');
                if (toggle) toggle.textContent = 'Kapat';
            }
            highlightObject(obj);
            updatePlacementPanel(`${obj.label} seçildi. Öğrenme kartı açıldı.`);
        }
        function moveSelectedPlacement(dt) {
            const obj = three.placement.selected;
            if (!three.placement.enabled || !obj) return false;
            const k = placementKeyFor(obj);
            if (three.placement.locked[k]) { updatePlacementPanel('Bu obje kilitli. Taşımak için önce kilidi aç.'); return true; }
            const ks = three.keyState || {};
            const fine = ks['shift'];
            const step = (fine ? 0.75 : 2.8) * dt;
            let dx = 0, dz = 0;
            if (ks['w'] || ks['arrowup']) dz -= step;
            if (ks['s'] || ks['arrowdown']) dz += step;
            if (ks['a'] || ks['arrowleft']) dx -= step;
            if (ks['d'] || ks['arrowright']) dx += step;
            let rotated = false;
            const rotSpeed = (ks['shift'] ? 0.8 : 2.2) * dt;
            if (ks['z']) { obj.mesh.rotation.y -= rotSpeed; rotated = true; }
            if (ks['x']) { obj.mesh.rotation.y += rotSpeed; rotated = true; }
            if (ks['r']) { obj.mesh.rotation.y = 0; rotated = true; }
            obj.mesh.rotation.y = ((obj.mesh.rotation.y % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
            if (!dx && !dz && !rotated) return false;
            obj.mesh.position.x += dx;
            obj.mesh.position.z += dz;
            persistObjectPlacement(obj);
            return true;
        }


        function addObj(mesh, label, desc, opts = {}) { 
            const obj = { mesh, label, desc, opts };
            mesh.name = label || mesh.name || 'interactive-object';
            mesh.traverse?.(child => { child.userData.parentInteractive = obj; });
            mesh.userData.parentInteractive = obj;
            applySavedPlacement(obj);
            three.objects.push(obj); 
            three.scene.add(mesh);
            return obj;
        }
        function addDecor(mesh) { three.scene.add(mesh); return mesh; }
        function addAnimated(obj, type, opts = {}) { three.animated.push({ obj, type, ...opts }); return obj; }

        function buildRoomShell(tone) {
            const isOR = App.currentRoom === 'intraop';
            const isWard = !isOR;
            const dims = isOR ? { w: 17.2, d: 14.0, h: 4.2 } : { w: 13.6, d: 11.2, h: 3.65 };
            const backZ = -dims.d / 2;
            const sideX = dims.w / 2;
            const frontZ = dims.d / 2;
            const floorColor = isOR ? 0xb7c8cc : 0xb8c0c7;
            const backColor = isOR ? 0xd7e1e6 : 0xc9b08d;
            const wallL = isOR ? 0xe6ecef : 0xe2ddd5;
            const wallR = isOR ? 0xe7ecef : 0xe7e4de;

            const floor = box(dims.w, 0.06, dims.d, floorColor, 0, -0.03, 0, { roughness: 0.82 });
            floor.receiveShadow = true; addShellDecor(floor);
            addShellDecor(box(dims.w, 0.08, dims.d, 0xe9edf0, 0, dims.h, 0, { roughness: 0.90 }));
            addShellDecor(box(dims.w, dims.h, 0.10, backColor, 0, dims.h / 2, backZ, { roughness: 0.78 }));
            addShellDecor(box(0.10, dims.h, dims.d, wallL, -sideX, dims.h / 2, 0, { roughness: 0.80 }));
            addShellDecor(box(0.10, dims.h, dims.d, wallR, sideX, dims.h / 2, 0, { roughness: 0.80 }));
            const frontSideWallW = (isOR ? 3.0 : 2.0) * 0.30; // yan beyaz ön blokların yalnızca %30'u bırakılır
            addShellDecor(box(frontSideWallW, dims.h, 0.10, 0xe4e7ea, -sideX + (frontSideWallW / 2), dims.h / 2, frontZ, { roughness: 0.82 }));
            addShellDecor(box(frontSideWallW, dims.h, 0.10, 0xe4e7ea, sideX - (frontSideWallW / 2), dims.h / 2, frontZ, { roughness: 0.82 }));
            // merkezi ön blok kaldırıldı: preop, intraop ve postop sahnelerde görüşü kapatan dikdörtgen ayırıcı kullanılmıyor.

            if (isWard) {
                // floor zones inspired by the animated room prototype
                addShellDecor(box(4.60, 0.012, dims.d - 1.4, 0x9aa5ad, 2.20, 0.012, 0.10, { transparent: true, opacity: 0.35, receiveShadow: true }));
                addShellDecor(box(2.80, 0.014, dims.d - 1.5, 0xd7c6a4, -4.10, 0.014, 0.08, { transparent: true, opacity: 0.30, receiveShadow: true }));

                // chair rail / back-wall trim
                addShellDecor(box(dims.w, 0.09, 0.08, 0xffffff, 0, 1.16, backZ + 0.08, { roughness: 0.52 }));

                // ceiling grid
                for (let x = -6.2; x <= 6.2; x += 1.1) addShellDecor(box(0.012, 0.02, dims.d, 0xc8ccd1, x, dims.h - 0.04, 0, { castShadow: false }));
                for (let z = -4.8; z <= 4.8; z += 1.1) addShellDecor(box(dims.w, 0.02, 0.012, 0xc8ccd1, 0, dims.h - 0.035, z, { castShadow: false }));
                [[-4.0,-3.4],[-1.4,-3.4],[1.4,-3.4],[4.0,-3.4],[-4.0,0.0],[-1.4,0.0],[1.4,0.0],[4.0,0.0]].forEach((p, i) => {
                    const l = cyl(0.23, 0.23, 0.03, 0xfffbdf, p[0], dims.h - 0.09, p[1], { emissive: 0xfff4c8, emissiveIntensity: 0.52, castShadow: false, seg: 24 });
                    l.rotation.x = Math.PI / 2;
                    addShellDecor(l);
                    addAnimated(l, 'pulse', { speed: 0.6 + i * 0.02, base: 0.08, amp: 0.02 });
                });

                // artwork on right wall
                const art = groupAt(sideX - 0.18, 2.02, -1.4);
                art.rotation.y = -Math.PI / 2;
                art.add(box(0.90, 0.06, 1.15, 0xb69a6e, 0, 0, 0));
                art.add(box(0.78, 0.07, 1.02, 0xf3f1ec, 0, 0.006, 0));
                art.add(sphere(0.18, 0xffffff, -0.08, 0.04, 0.08, { emissive: 0xffffff, emissiveIntensity: 0.04 }));
                addShellDecor(art);

                // left side-wall sink / cabinet zone aligned parallel to the patient bed
                const sink = groupAt(-6.05, 0.0, -0.40);
                sink.rotation.y = Math.PI / 2;
                sink.add(box(2.20, 0.76, 0.78, 0xf5f3ef, 0, 0.44, 0.0, { roughness: 0.42 }));
                sink.add(box(2.42, 0.09, 0.88, 0xfdfdfb, 0, 0.90, 0, { roughness: 0.34 }));
                sink.add(box(0.80, 0.10, 0.45, 0xd8dee3, -0.64, 0.95, 0.02, { roughness: 0.28, metalness: 0.12 }));
                sink.add(cyl(0.035, 0.035, 0.36, 0xa7b0b8, -0.64, 1.07, -0.24, { metalness: 0.3 }));
                sink.add(cyl(0.025, 0.025, 0.42, 0xa7b0b8, -0.64, 1.24, -0.10, { axis: 'z', metalness: 0.3 }));
                sink.add(box(0.58, 0.32, 0.18, 0x202933, -1.70, 1.55, -0.42, { roughness: 0.34 }));
                sink.add(box(1.58, 0.82, 0.035, 0xcde2ed, -0.70, 1.96, -0.45, { transparent: true, opacity: 0.72, roughness: 0.12 }));
                sink.add(box(0.64, 0.80, 0.44, 0x5a4639, 0.94, 0.46, 0.18, { roughness: 0.55 }));
                sink.add(box(0.54, 0.02, 0.03, 0xd8d0c4, 0.94, 0.30, -0.01, { metalness: 0.12 }));
                sink.add(box(0.54, 0.02, 0.03, 0xd8d0c4, 0.94, 0.50, -0.01, { metalness: 0.12 }));
                sink.add(box(0.54, 0.02, 0.03, 0xd8d0c4, 0.94, 0.70, -0.01, { metalness: 0.12 }));
                sink.add(box(0.38, 0.56, 0.10, 0xf3f6f8, -1.86, 1.68, -0.40, { roughness: 0.35 }));
                sink.add(box(0.44, 0.28, 0.10, 0xf2f5f7, -1.30, 1.74, -0.40, { roughness: 0.35 }));
                sink.add(box(0.44, 0.28, 0.10, 0xf2f5f7, -0.76, 1.74, -0.40, { roughness: 0.35 }));
                addShellDecor(sink);

                // visitor sofa/area on right as decor
                const sofa = groupAt(5.10, 0.0, -0.35);
                sofa.add(box(0.92, 0.32, 0.92, 0x56738c, 0, 0.45, 0, { roughness: 0.62 }));
                sofa.add(box(0.92, 0.90, 0.20, 0x5f7f98, 0, 0.98, -0.35, { roughness: 0.64 }));
                sofa.add(box(0.18, 0.54, 0.92, 0x516b82, -0.52, 0.62, 0, { roughness: 0.66 }));
                sofa.add(box(0.18, 0.54, 0.92, 0x516b82, 0.52, 0.62, 0, { roughness: 0.66 }));
                sofa.add(box(0.82, 0.04, 0.34, 0xf0f3f6, -0.20, 0.85, 0.80, { roughness: 0.42 }));
                sofa.add(cyl(0.035, 0.035, 0.85, 0x98a4ae, -0.54, 0.44, 0.80, { metalness: 0.2 }));
                addShellDecor(sofa);

                // subtle warm accent bar on back wall
                const accent = box(6.6, 0.035, 0.06, 0xffe8bf, 0, 3.08, backZ + 0.11, { emissive: 0xffd08a, emissiveIntensity: 0.38, castShadow: false });
                addShellDecor(accent); addAnimated(accent, 'pulse', { speed: 0.45, base: 0.06, amp: 0.02 });
            } else {
                // OR ceiling rails and panel lights
                for (let z = -3.2; z <= 3.2; z += 2.1) addShellDecor(box(dims.w - 1.4, 0.035, 0.06, 0x91a4b2, 0, dims.h - 0.10, z, { metalness: .18, roughness: .50 }));
                [-2.8, -0.9, 1.0, 2.9].forEach((z, row) => {
                    for (let i = -2; i <= 2; i++) {
                        const l = box(1.20, 0.04, 0.24, 0xdbeaf0, i * 1.85, dims.h - 0.16, z, { emissive: 0xc9fbff, emissiveIntensity: 0.36 });
                        addShellDecor(l); addAnimated(l, 'pulse', { speed: 0.52 + row * .03, base: 0.12, amp: 0.02 });
                    }
                });
                addShellDecor(box(1.40, 2.30, 0.06, 0x95a7b5, sideX - 1.35, 1.15, backZ + 0.06, { roughness: 0.55 }));
                addShellDecor(box(1.35, 0.85, 0.04, 0xcde2ed, -sideX + 1.55, 2.22, backZ + 0.07, { emissive: 0x5cc4d6, emissiveIntensity: 0.10, transparent: true, opacity: 0.40 }));
                addShellDecor(box(1.80, 0.95, 0.035, 0xeef3f6, 0, 2.10, backZ + 0.08, { roughness: 0.55 }));
                const sterile = box(4.2, 0.015, 2.8, 0x2f8f6a, 0.45, 0.015, 0.25, { transparent: true, opacity: 0.15, emissive: 0x2f8f6a, emissiveIntensity: 0.10 });
                addObj(sterile, 'Steril Alan Sınırı', 'Bu alan fiziksel bariyer değildir; öğrenci steril alan ihlalini fark etmeli ve ekibe bildirmelidir.', { clinicalKey: 'sterile-zone', severity: 'warn' });
            }
        }
